//! C FFI shim for prmi. See `include/prmi.h` (generated by build.rs).

#![allow(non_camel_case_types)]
#![warn(missing_docs)]

mod errors;
mod handle;

use crate::errors::{clear_last_error, set_last_error, with_last_error};
use crate::handle::{prmi_index_t, Handle};
use libc::size_t;
use prmi::index::LearnedIndex;
use std::ffi::CStr;
use std::os::raw::{c_char, c_int};
use std::path::Path;

/// Packed-pac byte length (`ceil(num_bases / 4)`) as `usize`, or `None` if the
/// value does not fit `usize` (only possible on narrow-`usize` targets). Guards
/// the u64→usize narrowing before a packed-pac slice is constructed.
#[inline]
fn packed_pac_bytes(pac_num_bases: u64) -> Option<usize> {
    usize::try_from(pac_num_bases.div_ceil(4)).ok()
}

/// Open a sidecar by prefix; expects `<prefix>.{meta,sa,l1,l2}`.
///
/// Returns 0 on success and writes the handle to *out_handle.
/// Returns negative on error; *out_handle is set to NULL.
///
/// # Safety
/// `sidecar_prefix` must be a valid NUL-terminated C string. `out_handle`
/// must be a valid writable pointer.
#[no_mangle]
pub unsafe extern "C" fn prmi_open(
    sidecar_prefix: *const c_char,
    out_handle: *mut *mut prmi_index_t,
) -> c_int {
    clear_last_error();
    if sidecar_prefix.is_null() || out_handle.is_null() {
        set_last_error("prmi_open: null pointer argument");
        // Clear any stale handle the caller is reusing (only when out_handle
        // itself is non-null and thus safe to write through).
        if !out_handle.is_null() {
            unsafe { *out_handle = std::ptr::null_mut() };
        }
        return -1;
    }
    let cstr = unsafe { CStr::from_ptr(sidecar_prefix) };
    let s = match cstr.to_str() {
        Ok(s) => s,
        Err(_) => {
            set_last_error("prmi_open: prefix is not valid UTF-8");
            unsafe { *out_handle = std::ptr::null_mut() };
            return -2;
        }
    };
    match LearnedIndex::open(Path::new(s)) {
        Ok(idx) => {
            unsafe { *out_handle = Handle::new(idx).into_raw() };
            0
        }
        Err(e) => {
            set_last_error(&format!("{e}"));
            unsafe { *out_handle = std::ptr::null_mut() };
            -3
        }
    }
}

/// Open a sidecar previously loaded into shared-memory-backed storage via
/// `prmi shm load`. `shm_path` is the path to the shm blob (typically
/// `/dev/shm/<name>` on Linux or `/tmp/<name>` on macOS).
///
/// Pages are mmap'd with `MAP_SHARED`; multiple processes opening the same
/// `shm_path` share OS page-cache pages without re-paying I/O or page-fault
/// costs after the first open.
///
/// Returns 0 on success and writes the handle to `*out_handle`. Returns
/// negative on error; `*out_handle` is set to NULL.
///
/// Post-open semantics are identical to `prmi_open`. The handle must be
/// closed with `prmi_close`.
///
/// Thread-safe after return.
///
/// # Safety
/// `shm_path` must be a valid NUL-terminated C string. `out_handle` must be
/// a valid writable pointer.
#[no_mangle]
pub unsafe extern "C" fn prmi_open_shm(
    shm_path: *const c_char,
    out_handle: *mut *mut prmi_index_t,
) -> c_int {
    clear_last_error();
    if shm_path.is_null() || out_handle.is_null() {
        set_last_error("prmi_open_shm: null pointer argument");
        // Clear any stale handle the caller is reusing (only when out_handle
        // itself is non-null and thus safe to write through).
        if !out_handle.is_null() {
            unsafe { *out_handle = std::ptr::null_mut() };
        }
        return -1;
    }
    let cstr = unsafe { CStr::from_ptr(shm_path) };
    let s = match cstr.to_str() {
        Ok(s) => s,
        Err(_) => {
            set_last_error("prmi_open_shm: shm_path is not valid UTF-8");
            unsafe { *out_handle = std::ptr::null_mut() };
            return -2;
        }
    };
    match LearnedIndex::open_shm(std::path::Path::new(s)) {
        Ok(idx) => {
            unsafe { *out_handle = Handle::new(idx).into_raw() };
            0
        }
        Err(e) => {
            set_last_error(&format!("{e}"));
            unsafe { *out_handle = std::ptr::null_mut() };
            -3
        }
    }
}

/// Release all resources held by the handle. Safe to call with NULL.
///
/// # Safety
/// `handle` must be NULL or have been returned by `prmi_open` (or
/// `prmi_open_shm`) and not yet closed.
#[no_mangle]
pub unsafe extern "C" fn prmi_close(handle: *mut prmi_index_t) {
    if handle.is_null() {
        return;
    }
    drop(unsafe { Handle::from_raw(handle) });
}

/// Thread-local last-error string. Valid until the next prmi_* call on
/// the same thread. Never returns NULL — empty string if no error.
#[no_mangle]
pub extern "C" fn prmi_last_error_message() -> *const c_char {
    with_last_error(|c| c.as_ptr())
}

/// Predict the SA position for a 32-mer key.
///
/// Returns 0 on success; negative on error. Writes the predicted SA position
/// and the error bound to the out-pointers.
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open`. Both out-pointers must
/// be valid writable u64 locations.
#[no_mangle]
pub unsafe extern "C" fn prmi_lookup(
    handle: *const prmi_index_t,
    key: u64,
    out_predicted_sa_pos: *mut u64,
    out_err: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null() || out_predicted_sa_pos.is_null() || out_err.is_null() {
        set_last_error("prmi_lookup: null pointer argument");
        return -1;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let (pos, err) = h.idx.lookup(key);
    unsafe {
        *out_predicted_sa_pos = pos;
        *out_err = err;
    }
    0
}

/// Number of SA entries in the loaded sidecar.
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open`, or NULL (returns 0).
#[no_mangle]
pub unsafe extern "C" fn prmi_sa_num(handle: *const prmi_index_t) -> size_t {
    if handle.is_null() {
        return 0;
    }
    unsafe { Handle::as_ref(handle) }.idx.sa_num() as size_t
}

/// Reference length (`l_pac`, forward-strand base count) the sidecar was built
/// against, as recorded in its metadata. A consumer validates that a sidecar
/// belongs to the loaded reference by comparing this to the FM-index `l_pac` —
/// the genome-identity check that a tiered (filtered-SA) sidecar needs, since
/// such a sidecar's `sa_num` is intentionally smaller than `2*l_pac+1`.
///
/// # Returns
/// `l_pac` for a valid handle; `0` for a NULL handle, or if the fenced metadata
/// read panics (`l_pac()` is infallible, so the panic path is defensive only).
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open`, or NULL (returns 0).
#[no_mangle]
pub unsafe extern "C" fn prmi_l_pac(handle: *const prmi_index_t) -> u64 {
    if handle.is_null() {
        return 0;
    }
    // `l_pac()` is an infallible metadata read, but fence it anyway so no panic
    // can cross the FFI boundary; a panic falls back to the same `0` sentinel as
    // the NULL-handle case.
    let h = unsafe { Handle::as_ref(handle) };
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| h.idx.l_pac())).unwrap_or(0)
}

/// Whether the loaded sidecar carries an inverse suffix array (`.isa`), enabling
/// the `prmi_isa_at` launch hint / `mem_search` no-search fast path. Returns 1 if
/// present, else 0 (also 0 for a NULL handle or an shm-opened index, which does
/// not carry the `.isa`). The consumer branches on this at open time.
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open`, or NULL (returns 0).
#[no_mangle]
pub unsafe extern "C" fn prmi_has_isa(handle: *const prmi_index_t) -> c_int {
    if handle.is_null() {
        return 0;
    }
    c_int::from(unsafe { Handle::as_ref(handle) }.idx.has_isa())
}

/// Inverse suffix array lookup: given a reference position `refpos` (0-based in
/// the 2× doubled-coordinate space prmi indexes), write its SA index to
/// `*out_sa_index`. This is the exact launch hint to feed back as `est_hint` to
/// `prmi_mem_search` (BWA-MEME's `ref2sa`).
///
/// Returns 0 on success; `-1` null handle/out-ptr, `-2` `refpos` has no
/// inverse-SA entry (out of range for a dense ISA, or not in the keep-set for a
/// sparse/tiered ISA), `-3` internal panic or a corrupt `.isa` (out-of-range SA
/// index), `-5` the loaded sidecar has no `.isa` (build with `prmi build
/// --with-isa`).
///
/// # Safety
/// `handle` valid or NULL; `out_sa_index` writable on success.
#[no_mangle]
pub unsafe extern "C" fn prmi_isa_at(
    handle: *const prmi_index_t,
    refpos: u64,
    out_sa_index: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null() || out_sa_index.is_null() {
        set_last_error("prmi_isa_at: null handle or out_sa_index");
        return -1;
    }
    // Do ALL work — handle deref, `.isa` presence check, and the lookup — inside
    // the catch_unwind boundary so no panic from any of them can unwind across
    // `extern "C"` (UB). `isa_at` returns None when refpos is out of range (dense)
    // or not in the keep-set (sparse/tiered): there is no launch hint, so report
    // not-found rather than indexing out of bounds. A tiered ISA's valid refpos
    // space is the genome (up to 2*l_pac), NOT sa_num (the kept-entry count), so
    // we cannot bound-check against sa_num — isa_at does the right check itself.
    enum IsaAtOutcome {
        NoIsa,
        Miss,
        Corrupt { sa_index: u64, sa_num: u64 },
        Hit(u64),
    }
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        let h = unsafe { Handle::as_ref(handle) };
        if !h.idx.has_isa() {
            return IsaAtOutcome::NoIsa;
        }
        // The returned value is an SA rank fed straight back to bwa-mem3 as a
        // launch hint; a malformed `.isa` body could yield a rank past the SA, so
        // bound-check it here rather than let an out-of-range index propagate.
        let sa_num = h.idx.sa_num();
        match h.idx.isa_at(refpos) {
            Some(sa_index) if sa_index < sa_num => IsaAtOutcome::Hit(sa_index),
            Some(sa_index) => IsaAtOutcome::Corrupt { sa_index, sa_num },
            None => IsaAtOutcome::Miss,
        }
    }));
    match result {
        Ok(IsaAtOutcome::Hit(sa_index)) => {
            unsafe { *out_sa_index = sa_index };
            0
        }
        Ok(IsaAtOutcome::NoIsa) => {
            set_last_error("prmi_isa_at: sidecar has no .isa (build with --with-isa)");
            -5
        }
        Ok(IsaAtOutcome::Miss) => {
            set_last_error(
                "prmi_isa_at: refpos has no inverse-SA entry (out of range or not in keep-set)",
            );
            -2
        }
        Ok(IsaAtOutcome::Corrupt { sa_index, sa_num }) => {
            set_last_error(&format!(
                "prmi_isa_at: .isa returned out-of-range SA index {sa_index} >= sa_num {sa_num}"
            ));
            -3
        }
        Err(_) => {
            set_last_error("prmi_isa_at: internal panic");
            -3
        }
    }
}

/// Whether SA-probe counting is compiled in: `1` if `prmi` was built with the
/// `spectrum-probe-count` feature (so `prmi_probe_count_get` returns meaningful
/// numbers), `0` otherwise. Let a consumer distinguish "zero probes" from
/// "counting disabled" before trusting `prmi_probe_count_get`.
///
/// Probe counting is OFF in normal release builds (the production hot path
/// carries no counter); enable it for `--seeding-only` instrumentation runs by
/// building `prmi-sys` with `--features spectrum-probe-count`.
#[no_mangle]
pub extern "C" fn prmi_probe_count_enabled() -> c_int {
    #[cfg(feature = "spectrum-probe-count")]
    {
        1
    }
    #[cfg(not(feature = "spectrum-probe-count"))]
    {
        0
    }
}

/// Reset the CALLING THREAD's SA-probe counter to zero. The counter is thread-
/// local, so each worker thread instruments only its own search calls — reset
/// before a call (or batch) and read with `prmi_probe_count_get` after, on the
/// same thread. No-op unless built with `spectrum-probe-count`.
#[no_mangle]
pub extern "C" fn prmi_probe_count_reset() {
    #[cfg(feature = "spectrum-probe-count")]
    {
        prmi::index::spectrum::probe_count::reset();
    }
}

/// Read the CALLING THREAD's SA-probe count (cold `sa_position_for` reads) since
/// the last `prmi_probe_count_reset`. One probe == one suffix-array position read
/// — the dominant cost of `prmi_mem_search`, `prmi_mem_search_backward`, and the
/// spectrum calls — so this is the in-situ confirmation of the per-call probe
/// reduction the `est_hint` (`prmi_isa_at`) launch buys. Returns `0` when built
/// without `spectrum-probe-count` (check `prmi_probe_count_enabled`).
#[no_mangle]
pub extern "C" fn prmi_probe_count_get() -> u64 {
    #[cfg(feature = "spectrum-probe-count")]
    {
        prmi::index::spectrum::probe_count::get()
    }
    #[cfg(not(feature = "spectrum-probe-count"))]
    {
        0
    }
}

/// Global max prediction error stored in the sidecar.
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open`, or NULL (returns 0).
#[no_mangle]
pub unsafe extern "C" fn prmi_max_error_bound(handle: *const prmi_index_t) -> u64 {
    if handle.is_null() {
        return 0;
    }
    unsafe { Handle::as_ref(handle) }.idx.max_error_bound()
}

/// Format magic string from the loaded sidecar (e.g. `"PRMIv2"`). Always non-NULL.
///
/// The returned pointer is valid for the lifetime of the handle. If `handle`
/// is NULL, returns a pointer to a static empty C string (`""`).
///
/// # Safety
/// `handle` may be NULL. If non-NULL, it must be a valid handle from
/// `prmi_open` or `prmi_open_shm` that has not yet been closed.
#[no_mangle]
pub unsafe extern "C" fn prmi_format_version(handle: *const prmi_index_t) -> *const c_char {
    static EMPTY: &[u8] = b"\0";
    if handle.is_null() {
        return EMPTY.as_ptr() as *const c_char;
    }
    unsafe { Handle::as_ref(handle) }.magic.as_ptr()
}

/// Tokenize up to 32 bases (2-bit packed, MSB-first, T-pad short queries)
/// into a u64 key suitable for prmi_lookup. Mirrors prmi's internal
/// tokenization exactly, so callers don't have to reimplement it.
///
/// `bases` points to at least `bases_len` unpacked bytes (values 0..=3).
/// `len` is the number of valid bases to use; values > 32 or > `bases_len`
/// are clamped to `min(len, bases_len, 32)`.
///
/// Returns 0 on success and writes the key to `*out_key`; returns -1 on
/// any pointer being null or `len < 0`.
///
/// # Safety
/// `bases` must point to at least `bases_len` valid bytes when `bases_len > 0`.
/// `out_key` must be a valid writable u64 location.
#[no_mangle]
pub unsafe extern "C" fn prmi_tokenize_32mer(
    bases: *const u8,
    bases_len: size_t,
    len: c_int,
    out_key: *mut u64,
) -> c_int {
    clear_last_error();
    if bases.is_null() || out_key.is_null() || len < 0 {
        set_last_error("prmi_tokenize_32mer: null pointer or negative len");
        return -1;
    }
    let n = (len as usize).min(32).min(bases_len);
    let slice = unsafe { std::slice::from_raw_parts(bases, n) };
    let key = prmi::encoding::tokenize_32mer(slice, n);
    unsafe { *out_key = key };
    0
}

/// Read `count` SA positions starting at SA index `k` into the
/// caller-provided `out_positions` buffer.
///
/// `out_positions` must point to at least `count` u64s. Each position
/// is a forward-strand genome offset (per the sidecar's `[sa] strand`
/// convention). For reverse-strand matches, tokenize the
/// reverse-complement of the query and call `prmi_lookup` a second time.
///
/// Returns 0 on success and 0 with no writes if `count == 0`. Error codes:
///   - `-1` — `handle` is NULL.
///   - `-2` — `out_positions` is NULL with `count > 0`.
///   - `-3` — `count` does not fit in `usize` on this target.
///   - `-4` — range `[k, k + count)` exceeds `sa_num`, or another internal
///     error from `LearnedIndex::sa_positions`; see `prmi_last_error_message`.
///
/// These codes are part of the stable ABI; downstream callers may match
/// against them. `prmi_last_error_message()` always carries a human-readable
/// description.
///
/// Thread-safe: concurrent calls on the same handle are intended and safe.
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open` (or NULL → error).
/// `out_positions` must point to writable memory of size
/// `count * sizeof(uint64_t)` when count > 0.
#[no_mangle]
pub unsafe extern "C" fn prmi_sa_positions(
    handle: *const prmi_index_t,
    k: u64,
    count: u64,
    out_positions: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null() {
        set_last_error("prmi_sa_positions: NULL handle");
        return -1;
    }
    if count == 0 {
        return 0;
    }
    if out_positions.is_null() {
        set_last_error("prmi_sa_positions: NULL out_positions with count > 0");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let count_usize = match usize::try_from(count) {
        Ok(c) => c,
        Err(_) => {
            set_last_error("prmi_sa_positions: count exceeds usize range");
            return -3;
        }
    };
    let slice = unsafe { std::slice::from_raw_parts_mut(out_positions, count_usize) };
    match h.idx.sa_positions(k, slice) {
        Ok(()) => 0,
        Err(e) => {
            set_last_error(&format!("prmi_sa_positions: {e}"));
            -4
        }
    }
}

/// Read `n_out` raw 2× SA positions starting at SA index `k`, sampling every
/// `step`-th entry: `out[j] = SA[k + j*step]`. Mirrors the FMI's strided fetch
/// for the `>max_occ` path (caller sets `step = s / max_occ`, `n_out = max_occ`).
///
/// Returns 0 on success; 0 with no writes if `n_out == 0`. Error codes:
///   - `-1` — `handle` is NULL.
///   - `-2` — `out_positions` is NULL with `n_out > 0`.
///   - `-3` — `n_out` does not fit in `usize` on this target.
///   - `-4` — last index `k + (n_out-1)*step >= sa_num`, overflow, or another
///     internal error from `LearnedIndex::sa_positions_strided`; see
///     `prmi_last_error_message`.
///
/// These codes are part of the stable ABI. `prmi_last_error_message()` always
/// carries a human-readable description.
///
/// Thread-safe: concurrent calls on the same handle are intended and safe.
///
/// # Safety
/// `handle` must be a valid handle from `prmi_open` (or NULL → error).
/// `out_positions` must point to writable memory of size
/// `n_out * sizeof(uint64_t)` when `n_out > 0`.
#[no_mangle]
pub unsafe extern "C" fn prmi_sa_positions_strided(
    handle: *const prmi_index_t,
    k: u64,
    step: u64,
    n_out: u64,
    out_positions: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null() {
        set_last_error("prmi_sa_positions_strided: NULL handle");
        return -1;
    }
    if n_out == 0 {
        return 0;
    }
    if out_positions.is_null() {
        set_last_error("prmi_sa_positions_strided: NULL out_positions with n_out > 0");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let n_out_usize = match usize::try_from(n_out) {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_sa_positions_strided: n_out exceeds usize range");
            return -3;
        }
    };
    let out = unsafe { std::slice::from_raw_parts_mut(out_positions, n_out_usize) };
    match h.idx.sa_positions_strided(k, step, out) {
        Ok(()) => 0,
        Err(e) => {
            set_last_error(&format!("prmi_sa_positions_strided: {e}"));
            -4
        }
    }
}

/// One SMEM spectrum breakpoint: the SA interval `[sa_start, sa_start+occ_count)`
/// matching the query to length `match_len`. Mirrors `prmi::index::spectrum::SmemStep`.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct prmi_smem_step_t {
    /// SA interval start index (raw 2× SA).
    pub sa_start: u64,
    /// Occurrence count = SA interval size (both strands, native to the 2× SA).
    pub occ_count: u64,
    /// Match length (LCP) at this breakpoint.
    pub match_len: u64,
}

/// `prmi_smem_step_t` and `prmi::index::spectrum::SmemStep` are both `#[repr(C)]`
/// with the same three `u64` fields in the same order, so an output buffer of
/// one can be filled in place as a slice of the other (used by the `*_fill`
/// paths below to avoid an intermediate `Vec`). This assertion guards
/// size/alignment; the field order is asserted by inspection and the `#[repr(C)]`
/// on both types (see `SmemStep`'s doc comment).
const _: () = {
    assert!(
        core::mem::size_of::<prmi_smem_step_t>()
            == core::mem::size_of::<prmi::index::spectrum::SmemStep>()
    );
    assert!(
        core::mem::align_of::<prmi_smem_step_t>()
            == core::mem::align_of::<prmi::index::spectrum::SmemStep>()
    );
};

/// Reinterpret a `prmi_smem_step_t` output buffer as a `SmemStep` slice so the
/// search core can fill it directly. Sound by the layout equivalence asserted
/// above.
///
/// # Safety
/// `out_steps` must be non-null and point to at least `len` writable
/// `prmi_smem_step_t` slots.
#[inline]
unsafe fn out_steps_as_smemstep<'a>(
    out_steps: *mut prmi_smem_step_t,
    len: usize,
) -> &'a mut [prmi::index::spectrum::SmemStep] {
    unsafe {
        std::slice::from_raw_parts_mut(out_steps as *mut prmi::index::spectrum::SmemStep, len)
    }
}

/// Forward spectrum from a pivot: writes the breakpoint trace (ascending match_len,
/// up to the maximal forward match) into the caller-allocated `out_steps`
/// (capacity `max_steps`), and the count to `*out_nsteps`. `nsteps <= query_len`,
/// so `max_steps >= query_len` always suffices.
///
/// `query` = read[pivot..], 2-bit 0..3. `pac` is the FORWARD pac in BWA bntpac
/// packed form (4 bases/byte); `pac_num_bases` = l_pac.
///
/// Returns 0 on success (out_nsteps may be 0 = no match), negative on error:
///   -1 null handle, -2 null/invalid arg, query_len<=0, pac_num_bases too large
///      for this platform, or max_steps beyond usize range, -3 internal/panic,
///   -4 max_steps < produced nsteps (buffer too small; *out_nsteps set to needed;
///      the first max_steps entries are written — re-run with a larger buffer).
///
/// # Safety
/// All pointers valid; `query` has `query_len` bytes; `pac` has
/// `ceil(pac_num_bases/4)` bytes; `out_steps` has capacity `max_steps`.
#[no_mangle]
pub unsafe extern "C" fn prmi_forward_spectrum(
    handle: *const prmi_index_t,
    query: *const u8,
    query_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
    out_steps: *mut prmi_smem_step_t,
    max_steps: u64,
    out_nsteps: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null()
        || query.is_null()
        || pac.is_null()
        || out_steps.is_null()
        || out_nsteps.is_null()
    {
        set_last_error("prmi_forward_spectrum: null pointer argument");
        return -1;
    }
    if query_len <= 0 {
        set_last_error("prmi_forward_spectrum: query_len must be > 0");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let q = unsafe { std::slice::from_raw_parts(query, query_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_forward_spectrum: pac_num_bases too large for this platform");
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };

    // Fill the caller's buffer directly (no intermediate Vec). `_fill` returns
    // the TOTAL step count even when it exceeds the buffer, so overflow is
    // detected without allocating. Guard the u64→usize narrowing so a buffer
    // length past `usize::MAX` (32-bit targets) can't silently truncate `out`.
    let max_steps_usize = match usize::try_from(max_steps) {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_forward_spectrum: max_steps exceeds usize range");
            return -2;
        }
    };
    let out = unsafe { out_steps_as_smemstep(out_steps, max_steps_usize) };
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        // `_auto` transparently uses the loaded `.kmt` table when present
        // (byte-identical output), else the full search.
        h.idx.forward_spectrum_auto_fill(q, pac_slice, enc, out)
    }));
    let nsteps = match result {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_forward_spectrum: internal panic");
            return -3;
        }
    };
    unsafe { *out_nsteps = nsteps as u64 };
    if nsteps as u64 > max_steps {
        set_last_error("prmi_forward_spectrum: max_steps too small");
        return -4;
    }
    0
}

/// Backward spectrum: refine a right-anchored interval leftward. `(sa_start,
/// occ_count)` and `anchor_len` come from a prior `prmi_forward_spectrum` step.
/// Each emitted step's `match_len` is the TOTAL span (`left_ext + anchor_len`).
/// Writes the trace into `out_steps` (capacity `max_steps`; `nsteps <= pivot+1`)
/// and the count to `*out_nsteps`. `read` is the full read (2-bit 0..=3, 1
/// base per byte); `pivot` = index where the right anchor begins (i.e.
/// `read[pivot..pivot+anchor_len)` is the anchored query). `pac` is the FORWARD
/// pac (BWA bntpac packed: 4 bases/byte, MSB-first); `pac_num_bases` = l_pac.
///
/// Returns 0 on success (out_nsteps may be 0 = no left extension exists),
/// negative on error:
///   -1 null handle/pointer, -2 invalid read_len (<=0)/pivot (<0), pac_num_bases
///      too large for this platform, or max_steps beyond usize range,
///   -3 internal/panic (including a contiguity-guard failure on a corrupt index),
///   -4 max_steps too small (*out_nsteps set to the needed count; the first
///      max_steps entries are written — re-run with a larger buffer).
///
/// # Safety
/// All pointers valid; `read` has `read_len` bytes; `pac` has
/// `ceil(pac_num_bases/4)` bytes; `out_steps` has capacity `max_steps`.
#[no_mangle]
pub unsafe extern "C" fn prmi_backward_spectrum(
    handle: *const prmi_index_t,
    sa_start: u64,
    occ_count: u64,
    anchor_len: u64,
    read: *const u8,
    read_len: c_int,
    pivot: c_int,
    pac: *const u8,
    pac_num_bases: u64,
    out_steps: *mut prmi_smem_step_t,
    max_steps: u64,
    out_nsteps: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null()
        || read.is_null()
        || pac.is_null()
        || out_steps.is_null()
        || out_nsteps.is_null()
    {
        set_last_error("prmi_backward_spectrum: null pointer argument");
        return -1;
    }
    if read_len <= 0 || pivot < 0 {
        set_last_error("prmi_backward_spectrum: invalid read_len or pivot");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let r = unsafe { std::slice::from_raw_parts(read, read_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_backward_spectrum: pac_num_bases too large for this platform");
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let pivot_us = pivot as usize;

    // Fill the caller's buffer directly (no intermediate Vec). Guard the
    // u64→usize narrowing so a buffer length past `usize::MAX` (32-bit targets)
    // can't silently truncate `out`.
    let max_steps_usize = match usize::try_from(max_steps) {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_backward_spectrum: max_steps exceeds usize range");
            return -2;
        }
    };
    let out = unsafe { out_steps_as_smemstep(out_steps, max_steps_usize) };
    let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        h.idx.backward_spectrum_fill(
            sa_start, occ_count, anchor_len, r, pivot_us, pac_slice, enc, out,
        )
    }));
    let nsteps = match result {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_backward_spectrum: internal panic (possible corrupt SA/ISA)");
            return -3;
        }
    };
    unsafe { *out_nsteps = nsteps as u64 };
    if nsteps as u64 > max_steps {
        set_last_error("prmi_backward_spectrum: max_steps too small");
        return -4;
    }
    0
}

/// One forward-spectrum batch task: read `query_len` bytes at `query_off` in the
/// shared queries arena; write up to `max_steps` steps at index `steps_off` in the
/// shared steps arena.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct prmi_fwd_task_t {
    /// Byte offset into the queries arena where this task's query begins.
    pub query_off: u64,
    /// Number of query bytes (= query length in bases).
    pub query_len: u32,
    /// Step index (not byte offset) into the steps arena where this task writes.
    pub steps_off: u32,
    /// Maximum number of steps this task may write; 0 triggers the -4 overflow path.
    pub max_steps: u32,
}

/// One backward-spectrum batch task.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct prmi_bwd_task_t {
    /// SA interval start (from a prior forward step).
    pub sa_start: u64,
    /// Occurrence count (from a prior forward step).
    pub occ_count: u64,
    /// Anchor match length (from a prior forward step).
    pub anchor_len: u64,
    /// Byte offset into the reads arena where this task's read begins.
    pub read_off: u64,
    /// Number of read bytes.
    pub read_len: u32,
    /// Pivot index within the read (where the right anchor starts).
    pub pivot: u32,
    /// Step index into the steps arena where this task writes.
    pub steps_off: u32,
    /// Maximum number of steps this task may write.
    pub max_steps: u32,
}

/// Run `ntasks` forward spectra with the correctness-first SERIAL strategy (one
/// kmt-accelerated `forward_spectrum` per task). For the memory-level-parallelism
/// variant, see `prmi_forward_spectrum_batch_lockstep` — byte-identical output,
/// faster on high-DRAM-latency microarchitectures, slower on low-latency ones
/// (measure). `queries_arena` holds all task query bytes (2-bit 0..3, caller-owned,
/// NOT copied); `queries_arena_len` is its size in bytes. Task i reads
/// `query_len` bytes at `query_off`. `steps_arena` is a shared caller-owned
/// output arena; `steps_arena_len` is its capacity in `prmi_smem_step_t`
/// elements. Task i writes up to `max_steps` steps starting at index
/// `steps_off`, and its produced count to `out_nsteps[i]` (0 if no match).
/// `pac` is the FORWARD pac (packed); `pac_num_bases` = l_pac.
///
/// Returns 0 on success. Error codes:
///   - `-1` — a required pointer is null: `handle`, `pac`, or (with `ntasks > 0`)
///     `tasks` / `out_nsteps`, or a `queries_arena` / `steps_arena` declared with a
///     non-zero length. A NULL arena with a zero declared length is accepted as the
///     canonical empty slice.
///   - `-2` — a task descriptor's query or steps window falls outside its arena,
///     or `ntasks` / a task's `query_off` / the packed pac length does not fit
///     `usize` on this target
///     (bad programming error); `prmi_last_error_message` names the offending
///     task index and which window violated the bound. The whole batch is
///     aborted on the first violation; no arena memory is read or written for
///     the violating task.
///   - `-3` — internal/panic.
///   - `-4` — a task's produced nsteps exceeds its `max_steps`; that task's
///     `out_nsteps[i]` is set to the needed count; its steps region is left
///     unwritten/partial — caller should re-run that task with a larger buffer.
///
/// # Safety
/// All pointers valid for their declared sizes; arenas at least as large as
/// declared; `out_nsteps` has `ntasks` u64 slots.
#[no_mangle]
pub unsafe extern "C" fn prmi_forward_spectrum_batch(
    handle: *const prmi_index_t,
    queries_arena: *const u8,
    queries_arena_len: u64,
    tasks: *const prmi_fwd_task_t,
    ntasks: u64,
    pac: *const u8,
    pac_num_bases: u64,
    steps_arena: *mut prmi_smem_step_t,
    steps_arena_len: u64,
    out_nsteps: *mut u64,
) -> c_int {
    unsafe {
        forward_spectrum_batch_impl(
            handle,
            queries_arena,
            queries_arena_len,
            tasks,
            ntasks,
            pac,
            pac_num_bases,
            steps_arena,
            steps_arena_len,
            out_nsteps,
            false,
        )
    }
}

/// Run `ntasks` forward spectra with the LOCKSTEP strategy: all tasks are driven
/// in parallel, batching their cold SA probe loads each round so the memory
/// latency overlaps (memory-level parallelism). Byte-identical output to
/// `prmi_forward_spectrum_batch` — same breakpoints, same order — differing only
/// in execution strategy. Faster on high-DRAM-latency microarchitectures (server
/// x86 / Graviton); can be SLOWER on low-latency ones (e.g. Apple Silicon, which
/// already hides the latency). A/B both entry points on the target hardware and
/// pick the winner. Same arguments and arena contract as
/// `prmi_forward_spectrum_batch`.
///
/// Drives the table-free forward search (it does not consult a loaded `.kmt`);
/// the MLP win is on the cold deep-probe path, which is also the byte-identity-
/// critical production path. Output still equals the kmt-accelerated serial entry.
///
/// Returns 0 on success. Error codes (identical to `prmi_forward_spectrum_batch`,
/// listed in full here so this entrypoint's contract is self-contained):
///   - `-1` — a required pointer is null: `handle`, `pac`, or (with `ntasks > 0`)
///     `tasks` / `out_nsteps`, or a `queries_arena` / `steps_arena` declared with a
///     non-zero length. A NULL arena with a zero declared length is accepted as the
///     canonical empty slice.
///   - `-2` — a task descriptor's query or steps window falls outside its arena, or
///     `ntasks` / a task's `query_off` / the packed pac length does not fit `usize`
///     on this target; `prmi_last_error_message` names the offending task index and
///     which window violated the bound. The whole batch is aborted on the first
///     violation; no arena memory is read or written for the violating task.
///   - `-3` — internal/panic.
///   - `-4` — a task's produced nsteps exceeds its `max_steps`; that task's
///     `out_nsteps[i]` is set to the needed count; its steps region is left
///     unwritten/partial — caller should re-run that task with a larger buffer.
///
/// # Safety
/// All pointers valid for their declared sizes; arenas at least as large as
/// declared; `out_nsteps` has `ntasks` u64 slots.
#[no_mangle]
pub unsafe extern "C" fn prmi_forward_spectrum_batch_lockstep(
    handle: *const prmi_index_t,
    queries_arena: *const u8,
    queries_arena_len: u64,
    tasks: *const prmi_fwd_task_t,
    ntasks: u64,
    pac: *const u8,
    pac_num_bases: u64,
    steps_arena: *mut prmi_smem_step_t,
    steps_arena_len: u64,
    out_nsteps: *mut u64,
) -> c_int {
    unsafe {
        forward_spectrum_batch_impl(
            handle,
            queries_arena,
            queries_arena_len,
            tasks,
            ntasks,
            pac,
            pac_num_bases,
            steps_arena,
            steps_arena_len,
            out_nsteps,
            true,
        )
    }
}

/// Write one forward task's steps into the shared `steps_arena`, setting
/// `*out_ns_i` to the step count. Returns `true` if the count exceeded
/// `t.max_steps` (the task's arena region is then left unwritten for the caller
/// to retry with a larger buffer). Used by the lockstep arm, whose
/// `forward_spectrum_lockstep` returns owned step vectors; the serial arm fills
/// the arena directly via `forward_spectrum_auto_fill` instead.
///
/// # Safety
/// `steps_arena` must have at least `t.steps_off + steps.len()` slots.
#[inline]
unsafe fn write_fwd_task_steps(
    steps_arena: *mut prmi_smem_step_t,
    t: &prmi_fwd_task_t,
    steps: &[prmi::index::spectrum::SmemStep],
    out_ns_i: &mut u64,
) -> bool {
    *out_ns_i = steps.len() as u64;
    if steps.len() as u64 > u64::from(t.max_steps) {
        return true;
    }
    if steps.is_empty() {
        // Canonical empty: nothing to write. Return before touching `steps_arena`,
        // which a caller may pass as `NULL + 0` (so `from_raw_parts_mut(NULL, 0)`
        // — UB — is never reached).
        return false;
    }
    let dst = unsafe {
        std::slice::from_raw_parts_mut(steps_arena.add(t.steps_off as usize), steps.len())
    };
    for (slot, s) in dst.iter_mut().zip(steps.iter()) {
        *slot = prmi_smem_step_t {
            sa_start: s.sa_start,
            occ_count: s.occ_count,
            match_len: s.match_len,
        };
    }
    false
}

/// Shared impl for the two forward-batch entry points. `lockstep == false` runs
/// the correctness-first serial loop (one kmt-accelerated `forward_spectrum` per
/// task); `lockstep == true` drives all tasks through `forward_spectrum_lockstep`
/// (memory-level parallelism via batched probe loads). Output is byte-identical
/// between the two strategies — they differ only in execution order and timing.
///
/// # Safety
/// All pointers valid for their declared sizes; arenas at least as large as
/// declared; `out_nsteps` has `ntasks` u64 slots.
#[allow(clippy::too_many_arguments)]
unsafe fn forward_spectrum_batch_impl(
    handle: *const prmi_index_t,
    queries_arena: *const u8,
    queries_arena_len: u64,
    tasks: *const prmi_fwd_task_t,
    ntasks: u64,
    pac: *const u8,
    pac_num_bases: u64,
    steps_arena: *mut prmi_smem_step_t,
    steps_arena_len: u64,
    out_nsteps: *mut u64,
    lockstep: bool,
) -> c_int {
    clear_last_error();
    if handle.is_null() || pac.is_null() {
        set_last_error("prmi_forward_spectrum_batch: null pointer");
        return -1;
    }
    if ntasks == 0 {
        return 0;
    }
    // `tasks` and `out_nsteps` have length `ntasks > 0`, so they must be non-null.
    if tasks.is_null() || out_nsteps.is_null() {
        set_last_error("prmi_forward_spectrum_batch: null tasks/out with ntasks > 0");
        return -1;
    }
    // A NULL arena is the canonical empty slice ONLY with a declared length of 0
    // (C callers pass empty buffers as `NULL + 0`); building such a slice from the
    // raw NULL pointer would be UB, so the per-task slices below branch to `&[]` /
    // `&mut []` for zero-length windows. Reject NULL when the caller declares a
    // non-empty arena.
    if queries_arena.is_null() && queries_arena_len != 0 {
        set_last_error(
            "prmi_forward_spectrum_batch: null queries_arena with queries_arena_len > 0",
        );
        return -1;
    }
    if steps_arena.is_null() && steps_arena_len != 0 {
        set_last_error("prmi_forward_spectrum_batch: null steps_arena with steps_arena_len > 0");
        return -1;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error(
                "prmi_forward_spectrum_batch: pac_num_bases too large for this platform",
            );
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let nt = match usize::try_from(ntasks) {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_forward_spectrum_batch: ntasks exceeds usize range");
            return -2;
        }
    };
    let tasks_s = unsafe { std::slice::from_raw_parts(tasks, nt) };
    let out_ns = unsafe { std::slice::from_raw_parts_mut(out_nsteps, nt) };

    // Validate all task descriptors against arena bounds before any I/O.
    for (i, t) in tasks_s.iter().enumerate() {
        // Guard the u64→usize narrowing used by `queries_arena.add(query_off)`
        // below; on a narrow-`usize` target a huge offset would misaddress.
        if usize::try_from(t.query_off).is_err() {
            set_last_error(&format!(
                "prmi_forward_spectrum_batch: task {i} query_off={} exceeds usize range",
                t.query_off
            ));
            return -2;
        }
        let query_end = (t.query_off as u128)
            .checked_add(t.query_len as u128)
            .map(|e| e <= queries_arena_len as u128)
            .unwrap_or(false);
        if !query_end {
            set_last_error(&format!(
                "prmi_forward_spectrum_batch: task {i} query window \
                 [query_off={}, query_len={}] out of queries_arena_len={}",
                t.query_off, t.query_len, queries_arena_len
            ));
            return -2;
        }
        let steps_end = (t.steps_off as u128)
            .checked_add(t.max_steps as u128)
            .map(|e| e <= steps_arena_len as u128)
            .unwrap_or(false);
        if !steps_end {
            set_last_error(&format!(
                "prmi_forward_spectrum_batch: task {i} steps window \
                 [steps_off={}, max_steps={}] out of steps_arena_len={}",
                t.steps_off, t.max_steps, steps_arena_len
            ));
            return -2;
        }
    }

    // `forward_spectrum_lockstep` materializes the full step trace of EVERY task
    // up front (its per-stepper `Vec<SmemStep>` grows unconditionally), whereas the
    // serial arm fills the caller's bounded arena directly and never allocates a
    // per-task vector. A sizing probe — a C caller passing no steps buffer to learn
    // the required `nsteps` before allocating — is exactly `steps_arena_len == 0`
    // (the bounds check above then forces every `max_steps == 0`). Route that case
    // through the bounded serial fill path so a probe cannot drive the unbounded
    // transient materialization just to be answered with `-4`. Output is
    // byte-identical between the two strategies, so the reported counts and the `-4`
    // return are unchanged; only the lost MLP (irrelevant when nothing is written)
    // differs.
    let use_lockstep = lockstep && steps_arena_len != 0;

    // One catch_unwind around the whole loop — panic anywhere → -3.
    let mut overflow = false;
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if use_lockstep {
            // Lockstep genuinely needs all tasks resident at once:
            // `forward_spectrum_lockstep` drives them together for memory-level
            // parallelism and returns one step vector per task. Write each result
            // through after the batched call.
            let fwd_tasks: Vec<_> = tasks_s
                .iter()
                .map(|t| {
                    // Empty query window → `&[]`; the arena may be the canonical
                    // `NULL + 0`, so never `from_raw_parts(NULL, 0)` (UB).
                    let q: &[u8] = if t.query_len == 0 {
                        &[]
                    } else {
                        unsafe {
                            std::slice::from_raw_parts(
                                queries_arena.add(t.query_off as usize),
                                t.query_len as usize,
                            )
                        }
                    };
                    prmi::index::spectrum::FwdTask { query: q }
                })
                .collect();
            let all_steps = h.idx.forward_spectrum_lockstep(&fwd_tasks, pac_slice, enc);
            debug_assert_eq!(all_steps.len(), tasks_s.len());
            // `zip` (not indexing) keeps the three collections paired safely.
            for ((t, out_ns_i), steps) in
                tasks_s.iter().zip(out_ns.iter_mut()).zip(all_steps.iter())
            {
                if unsafe { write_fwd_task_steps(steps_arena, t, steps, out_ns_i) } {
                    overflow = true;
                }
            }
        } else {
            for (i, t) in tasks_s.iter().enumerate() {
                // Empty query window → `&[]`; the arena may be the canonical
                // `NULL + 0`, so never `from_raw_parts(NULL, 0)` (UB).
                let q: &[u8] = if t.query_len == 0 {
                    &[]
                } else {
                    unsafe {
                        std::slice::from_raw_parts(
                            queries_arena.add(t.query_off as usize),
                            t.query_len as usize,
                        )
                    }
                };
                // Fill this task's arena region directly; `_fill` returns the total
                // count and writes at most `max_steps` steps (overflow → -4, caller
                // retries with a larger buffer). Empty step window → `&mut []`
                // (the steps arena may likewise be the canonical `NULL + 0`).
                let dst: &mut [prmi::index::spectrum::SmemStep] = if t.max_steps == 0 {
                    &mut []
                } else {
                    unsafe {
                        out_steps_as_smemstep(
                            steps_arena.add(t.steps_off as usize),
                            t.max_steps as usize,
                        )
                    }
                };
                let nsteps = h.idx.forward_spectrum_auto_fill(q, pac_slice, enc, dst);
                out_ns[i] = nsteps as u64;
                if nsteps as u64 > u64::from(t.max_steps) {
                    overflow = true;
                }
            }
        }
    }));
    if res.is_err() {
        set_last_error("prmi_forward_spectrum_batch: internal panic");
        return -3;
    }
    if overflow {
        set_last_error("prmi_forward_spectrum_batch: a task's max_steps too small");
        return -4;
    }
    0
}

/// Write one backward task's steps into the shared `steps_arena`, setting
/// `*out_ns_i` to the step count. Returns `true` if the count exceeded
/// `t.max_steps` (the task's arena region is then left unwritten for the caller
/// to retry with a larger buffer). Used by the lockstep arm, whose
/// `backward_spectrum_lockstep` returns owned step vectors; the serial arm fills
/// the arena directly via `backward_spectrum_fill` instead.
///
/// # Safety
/// `steps_arena` must have at least `t.steps_off + steps.len()` slots.
#[inline]
unsafe fn write_bwd_task_steps(
    steps_arena: *mut prmi_smem_step_t,
    t: &prmi_bwd_task_t,
    steps: &[prmi::index::spectrum::SmemStep],
    out_ns_i: &mut u64,
) -> bool {
    *out_ns_i = steps.len() as u64;
    if steps.len() as u64 > u64::from(t.max_steps) {
        return true;
    }
    if steps.is_empty() {
        // Canonical empty: nothing to write. Return before touching `steps_arena`,
        // which a caller may pass as `NULL + 0` (so `from_raw_parts_mut(NULL, 0)`
        // — UB — is never reached).
        return false;
    }
    let dst = unsafe {
        std::slice::from_raw_parts_mut(steps_arena.add(t.steps_off as usize), steps.len())
    };
    for (slot, s) in dst.iter_mut().zip(steps.iter()) {
        *slot = prmi_smem_step_t {
            sa_start: s.sa_start,
            occ_count: s.occ_count,
            match_len: s.match_len,
        };
    }
    false
}

/// Shared impl for the two backward-batch entry points. `lockstep == false` runs
/// the correctness-first serial loop (one `backward_spectrum` per task);
/// `lockstep == true` drives all tasks through `backward_spectrum_lockstep`
/// (memory-level parallelism via batched probe loads). Output is byte-identical
/// between the two strategies — they differ only in execution order and timing.
///
/// # Safety
/// All pointers valid for their declared sizes; arenas at least as large as
/// declared; `out_nsteps` has `ntasks` u64 slots.
#[allow(clippy::too_many_arguments)]
unsafe fn backward_spectrum_batch_impl(
    handle: *const prmi_index_t,
    reads_arena: *const u8,
    reads_arena_len: u64,
    tasks: *const prmi_bwd_task_t,
    ntasks: u64,
    pac: *const u8,
    pac_num_bases: u64,
    steps_arena: *mut prmi_smem_step_t,
    steps_arena_len: u64,
    out_nsteps: *mut u64,
    lockstep: bool,
) -> c_int {
    clear_last_error();
    if handle.is_null() || pac.is_null() {
        set_last_error("prmi_backward_spectrum_batch: null pointer");
        return -1;
    }
    if ntasks == 0 {
        return 0;
    }
    // `tasks` and `out_nsteps` have length `ntasks > 0`, so they must be non-null.
    if tasks.is_null() || out_nsteps.is_null() {
        set_last_error("prmi_backward_spectrum_batch: null tasks/out with ntasks > 0");
        return -1;
    }
    // A NULL arena is the canonical empty slice ONLY with a declared length of 0
    // (C callers pass empty buffers as `NULL + 0`); building such a slice from the
    // raw NULL pointer would be UB, so the per-task slices below branch to `&[]` /
    // `&mut []` for zero-length windows. Reject NULL when the caller declares a
    // non-empty arena.
    if reads_arena.is_null() && reads_arena_len != 0 {
        set_last_error("prmi_backward_spectrum_batch: null reads_arena with reads_arena_len > 0");
        return -1;
    }
    if steps_arena.is_null() && steps_arena_len != 0 {
        set_last_error("prmi_backward_spectrum_batch: null steps_arena with steps_arena_len > 0");
        return -1;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error(
                "prmi_backward_spectrum_batch: pac_num_bases too large for this platform",
            );
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let nt = match usize::try_from(ntasks) {
        Ok(n) => n,
        Err(_) => {
            set_last_error("prmi_backward_spectrum_batch: ntasks exceeds usize range");
            return -2;
        }
    };
    let tasks_s = unsafe { std::slice::from_raw_parts(tasks, nt) };
    let out_ns = unsafe { std::slice::from_raw_parts_mut(out_nsteps, nt) };

    // Validate all task descriptors against arena bounds before any I/O.
    for (i, t) in tasks_s.iter().enumerate() {
        // Guard the u64→usize narrowing used by `reads_arena.add(read_off)`
        // below; on a narrow-`usize` target a huge offset would misaddress.
        if usize::try_from(t.read_off).is_err() {
            set_last_error(&format!(
                "prmi_backward_spectrum_batch: task {i} read_off={} exceeds usize range",
                t.read_off
            ));
            return -2;
        }
        let read_end = (t.read_off as u128)
            .checked_add(t.read_len as u128)
            .map(|e| e <= reads_arena_len as u128)
            .unwrap_or(false);
        if !read_end {
            set_last_error(&format!(
                "prmi_backward_spectrum_batch: task {i} read window \
                 [read_off={}, read_len={}] out of reads_arena_len={}",
                t.read_off, t.read_len, reads_arena_len
            ));
            return -2;
        }
        let steps_end = (t.steps_off as u128)
            .checked_add(t.max_steps as u128)
            .map(|e| e <= steps_arena_len as u128)
            .unwrap_or(false);
        if !steps_end {
            set_last_error(&format!(
                "prmi_backward_spectrum_batch: task {i} steps window \
                 [steps_off={}, max_steps={}] out of steps_arena_len={}",
                t.steps_off, t.max_steps, steps_arena_len
            ));
            return -2;
        }
    }

    // One catch_unwind around the whole batch — panic anywhere (incl. contiguity
    // guard in backward_spectrum) → -3.
    let mut overflow = false;
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if lockstep {
            // Lockstep genuinely needs all tasks resident at once:
            // `backward_spectrum_lockstep` drives them together for memory-level
            // parallelism and returns one step vector per task. Write each result
            // through after the batched call.
            let bwd_tasks: Vec<_> = tasks_s
                .iter()
                .map(|t| {
                    // Empty read window → `&[]`; the arena may be the canonical
                    // `NULL + 0`, so never `from_raw_parts(NULL, 0)` (UB).
                    let read: &[u8] = if t.read_len == 0 {
                        &[]
                    } else {
                        unsafe {
                            std::slice::from_raw_parts(
                                reads_arena.add(t.read_off as usize),
                                t.read_len as usize,
                            )
                        }
                    };
                    prmi::index::spectrum::BwdTask {
                        sa_start: t.sa_start,
                        occ_count: t.occ_count,
                        anchor_len: t.anchor_len,
                        read,
                        pivot: t.pivot as usize,
                    }
                })
                .collect();
            let all_steps = h.idx.backward_spectrum_lockstep(&bwd_tasks, pac_slice, enc);
            for (i, steps) in all_steps.iter().enumerate() {
                if unsafe { write_bwd_task_steps(steps_arena, &tasks_s[i], steps, &mut out_ns[i]) }
                {
                    overflow = true;
                }
            }
        } else {
            // Serial: fill each task's arena region directly (mirroring
            // prmi_forward_spectrum_batch), with no per-task or whole-batch Vec.
            for (i, t) in tasks_s.iter().enumerate() {
                // Empty read window → `&[]`; the arena may be the canonical
                // `NULL + 0`, so never `from_raw_parts(NULL, 0)` (UB).
                let read: &[u8] = if t.read_len == 0 {
                    &[]
                } else {
                    unsafe {
                        std::slice::from_raw_parts(
                            reads_arena.add(t.read_off as usize),
                            t.read_len as usize,
                        )
                    }
                };
                // Empty step window → `&mut []` (the steps arena may likewise be the
                // canonical `NULL + 0`).
                let dst: &mut [prmi::index::spectrum::SmemStep] = if t.max_steps == 0 {
                    &mut []
                } else {
                    unsafe {
                        out_steps_as_smemstep(
                            steps_arena.add(t.steps_off as usize),
                            t.max_steps as usize,
                        )
                    }
                };
                let nsteps = h.idx.backward_spectrum_fill(
                    t.sa_start,
                    t.occ_count,
                    t.anchor_len,
                    read,
                    t.pivot as usize,
                    pac_slice,
                    enc,
                    dst,
                );
                out_ns[i] = nsteps as u64;
                if nsteps as u64 > u64::from(t.max_steps) {
                    overflow = true;
                }
            }
        }
    }));
    if res.is_err() {
        set_last_error("prmi_backward_spectrum_batch: internal panic");
        return -3;
    }
    if overflow {
        set_last_error("prmi_backward_spectrum_batch: a task's max_steps too small");
        return -4;
    }
    0
}

/// Run `ntasks` backward spectra with the correctness-first SERIAL strategy (one
/// `backward_spectrum` per task). This is the safe default: it never regresses
/// relative to calling `prmi_backward_spectrum` in a loop, and it amortizes the
/// FFI crossing. `reads_arena` holds all task read bytes (2-bit 0..3, caller-
/// owned, NOT copied); `reads_arena_len` is its size in bytes. Task i reads
/// `read_len` bytes at `read_off`. `steps_arena` is a shared caller-owned output
/// arena; `steps_arena_len` is its capacity in `prmi_smem_step_t` elements.
/// Task i writes up to `max_steps` steps at index `steps_off`, and its count to
/// `out_nsteps[i]` (0 if no left extension). `pac` is the FORWARD pac (packed);
/// `pac_num_bases` = l_pac.
///
/// For the memory-level-parallelism variant, see
/// `prmi_backward_spectrum_batch_lockstep` — byte-identical output, faster on
/// high-DRAM-latency microarchitectures, slower on low-latency ones (measure).
///
/// Returns 0 on success. Error codes:
///   - `-1` — a required pointer is null: `handle`, `pac`, or (with `ntasks > 0`)
///     `tasks` / `out_nsteps`, or a `reads_arena` / `steps_arena` declared with a
///     non-zero length. A NULL arena with a zero declared length is accepted as the
///     canonical empty slice.
///   - `-2` — a task descriptor's read or steps window falls outside its arena,
///     or `ntasks` / a task's `read_off` / the packed pac length does not fit
///     `usize` on this target;
///     `prmi_last_error_message` names the offending task index and window. The
///     whole batch is aborted on the first violation; no arena memory is read or
///     written for the violating task.
///   - `-3` — internal/panic (including a contiguity-guard failure).
///   - `-4` — a task's produced nsteps exceeds its `max_steps`; that task's
///     `out_nsteps[i]` is set to the needed count; its steps region is left
///     unwritten/partial.
///
/// # Safety
/// All pointers valid for their declared sizes; arenas at least as large as
/// declared; `out_nsteps` has `ntasks` u64 slots.
#[no_mangle]
pub unsafe extern "C" fn prmi_backward_spectrum_batch(
    handle: *const prmi_index_t,
    reads_arena: *const u8,
    reads_arena_len: u64,
    tasks: *const prmi_bwd_task_t,
    ntasks: u64,
    pac: *const u8,
    pac_num_bases: u64,
    steps_arena: *mut prmi_smem_step_t,
    steps_arena_len: u64,
    out_nsteps: *mut u64,
) -> c_int {
    unsafe {
        backward_spectrum_batch_impl(
            handle,
            reads_arena,
            reads_arena_len,
            tasks,
            ntasks,
            pac,
            pac_num_bases,
            steps_arena,
            steps_arena_len,
            out_nsteps,
            false,
        )
    }
}

/// Run `ntasks` backward spectra with the LOCKSTEP strategy: all tasks are driven
/// in parallel, batching their cold SA/model probe loads each round so the memory
/// latency overlaps (memory-level parallelism). Byte-identical output to
/// `prmi_backward_spectrum_batch` — same intervals, same order — differing only
/// in execution strategy. Faster on high-DRAM-latency microarchitectures (server
/// x86 / Graviton); can be SLOWER on low-latency ones (e.g. Apple Silicon, which
/// already hides the latency). A/B both entry points on the target hardware and
/// pick the winner. Same arguments and arena contract as
/// `prmi_backward_spectrum_batch`.
///
/// Returns 0 on success. Error codes (identical to `prmi_backward_spectrum_batch`,
/// listed in full here so this entrypoint's contract is self-contained):
///   - `-1` — a required pointer is null: `handle`, `pac`, or (with `ntasks > 0`)
///     `tasks` / `out_nsteps`, or a `reads_arena` / `steps_arena` declared with a
///     non-zero length. A NULL arena with a zero declared length is accepted as the
///     canonical empty slice.
///   - `-2` — a task descriptor's read or steps window falls outside its arena, or
///     `ntasks` / a task's `read_off` / the packed pac length does not fit `usize`
///     on this target; `prmi_last_error_message` names the offending task index and
///     window. The whole batch is aborted on the first violation; no arena memory
///     is read or written for the violating task.
///   - `-3` — internal/panic (including a contiguity-guard failure).
///   - `-4` — a task's produced nsteps exceeds its `max_steps`; that task's
///     `out_nsteps[i]` is set to the needed count; its steps region is left
///     unwritten/partial.
///
/// # Safety
/// All pointers valid for their declared sizes; arenas at least as large as
/// declared; `out_nsteps` has `ntasks` u64 slots.
#[no_mangle]
pub unsafe extern "C" fn prmi_backward_spectrum_batch_lockstep(
    handle: *const prmi_index_t,
    reads_arena: *const u8,
    reads_arena_len: u64,
    tasks: *const prmi_bwd_task_t,
    ntasks: u64,
    pac: *const u8,
    pac_num_bases: u64,
    steps_arena: *mut prmi_smem_step_t,
    steps_arena_len: u64,
    out_nsteps: *mut u64,
) -> c_int {
    unsafe {
        backward_spectrum_batch_impl(
            handle,
            reads_arena,
            reads_arena_len,
            tasks,
            ntasks,
            pac,
            pac_num_bases,
            steps_arena,
            steps_arena_len,
            out_nsteps,
            true,
        )
    }
}

/// `PRMI_MEM_WANT_INTERVAL`: also write `*out_sa_start`/`*out_occ` (the maximal
/// match's SA interval). When unset, only `*out_match_len` is written.
pub const PRMI_MEM_WANT_INTERVAL: u32 = 0x1;

/// One-shot maximal exact forward match. `query` is 2-bit bases (direction/RC
/// already applied by the caller); finds the longest prefix that occurs in the
/// reference. `*out_match_len` is ALWAYS written (0 if `query[0]` has no match).
/// With `flags & PRMI_MEM_WANT_INTERVAL`, also writes `*out_sa_start`/`*out_occ`
/// (the SA interval at `match_len`).
///
/// `est_hint`: `0` → prmi does its own model launch (full search). `> 0` → an
/// EXACT inverse-SA hint (from `prmi_isa_at(refpos)`): prmi confirms+extends from
/// that exact suffix and skips the model launch and interval narrowing
/// (BWA-MEME's `no_search`/`mem_search_tradeoff`). The hint MUST be a SA index in
/// the query's maximal-match interval; the launch changes speed, never the answer
/// — the result is byte-identical to `est_hint == 0`. A hint `>= sa_num` returns
/// `-2`.
///
/// Byte-identity: the returned `(sa_start, occ, match_len)` equals the maximal
/// step `prmi_forward_spectrum` produces for the same query.
///
/// Returns 0 on success; `-1` null handle/pointer, `-2` `query_len < 0`,
/// `pac_num_bases` too large for this platform, or `est_hint >= sa_num`,
/// `-3` internal panic.
///
/// # Safety
/// `handle` valid; `query` valid for `query_len` bytes; `pac` valid for
/// `ceil(pac_num_bases/4)` bytes; `out_match_len` writable; with the flag,
/// `out_sa_start`/`out_occ` writable.
#[no_mangle]
pub unsafe extern "C" fn prmi_mem_search(
    handle: *const prmi_index_t,
    query: *const u8,
    query_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
    est_hint: u64,
    flags: u32,
    out_match_len: *mut u32,
    out_sa_start: *mut u64,
    out_occ: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null() || query.is_null() || pac.is_null() || out_match_len.is_null() {
        set_last_error("prmi_mem_search: null pointer");
        return -1;
    }
    // When the interval is requested, validate its out-ptrs up FRONT so an error
    // return leaves all outputs (incl. `*out_match_len`) untouched.
    if flags & PRMI_MEM_WANT_INTERVAL != 0 && (out_sa_start.is_null() || out_occ.is_null()) {
        set_last_error("prmi_mem_search: WANT_INTERVAL set but out_sa_start/out_occ null");
        return -1;
    }
    // NOTE: `< 0` (not `<= 0` as in `prmi_forward_spectrum`) is deliberate —
    // `query_len == 0` is a valid empty query and yields `match_len == 0`.
    if query_len < 0 {
        set_last_error("prmi_mem_search: query_len < 0");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    // est_hint == 0 → internal model launch; > 0 → exact ISA launch (no_search).
    // An out-of-range hint is a caller error (the spec's no_search contract is
    // that the hint is the exact in-interval SA index).
    if est_hint != 0 && est_hint >= h.idx.sa_num() {
        set_last_error("prmi_mem_search: est_hint out of range");
        return -2;
    }
    let want_interval = flags & PRMI_MEM_WANT_INTERVAL != 0;
    let q = unsafe { std::slice::from_raw_parts(query, query_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_mem_search: pac_num_bases too large for this platform");
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if est_hint == 0 {
            h.idx.mem_search(q, pac_slice, enc)
        } else {
            h.idx
                .mem_search_from_hint(q, est_hint, want_interval, pac_slice, enc)
        }
    }));
    let m = match res {
        Ok(m) => m,
        Err(_) => {
            set_last_error("prmi_mem_search: internal panic");
            return -3;
        }
    };
    unsafe { *out_match_len = m.match_len as u32 };
    if flags & PRMI_MEM_WANT_INTERVAL != 0 {
        // out-ptrs were null-checked up front.
        unsafe {
            *out_sa_start = m.sa_start;
            *out_occ = m.occ;
        }
    }
    0
}

/// DIAGNOSTIC twin of [`prmi_mem_search`] with the per-call wrapper guards
/// removed — NO `clear_last_error`/`set_last_error`, NO `catch_unwind` — to A/B
/// the fixed FFI overhead the consumer pays on every seeding call (see
/// `examples/ffi_overhead.rs`). The search work and outputs are byte-identical to
/// `prmi_mem_search`; only the boundary cost differs (the correctness guards —
/// null/range/`packed_pac_bytes` narrowing — are kept). A search panic would
/// unwind across the FFI boundary (UB), so this is for measurement, or for builds
/// compiled `panic=abort` (where `catch_unwind` is already a no-op and this
/// matches the production path).
///
/// Returns the same codes as [`prmi_mem_search`] EXCEPT it never sets the
/// thread-local error string: `0` ok; `-1` null pointer (incl. `WANT_INTERVAL`
/// with null `out_sa_start`/`out_occ`); `-2` `query_len < 0`, `pac_num_bases` too
/// large for this platform, or `est_hint >= sa_num`.
///
/// # Safety
/// Same contract as [`prmi_mem_search`]; additionally the caller must ensure the
/// process is built `panic=abort` (or accept that a search panic is UB here).
#[allow(clippy::too_many_arguments)]
#[no_mangle]
pub unsafe extern "C" fn prmi_mem_search_lean(
    handle: *const prmi_index_t,
    query: *const u8,
    query_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
    est_hint: u64,
    flags: u32,
    out_match_len: *mut u32,
    out_sa_start: *mut u64,
    out_occ: *mut u64,
) -> c_int {
    if handle.is_null() || query.is_null() || pac.is_null() || out_match_len.is_null() {
        return -1;
    }
    if flags & PRMI_MEM_WANT_INTERVAL != 0 && (out_sa_start.is_null() || out_occ.is_null()) {
        return -1;
    }
    if query_len < 0 {
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    if est_hint != 0 && est_hint >= h.idx.sa_num() {
        return -2;
    }
    let want_interval = flags & PRMI_MEM_WANT_INTERVAL != 0;
    let q = unsafe { std::slice::from_raw_parts(query, query_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => return -2,
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let m = if est_hint == 0 {
        h.idx.mem_search(q, pac_slice, enc)
    } else {
        h.idx
            .mem_search_from_hint(q, est_hint, want_interval, pac_slice, enc)
    };
    unsafe { *out_match_len = m.match_len as u32 };
    if want_interval {
        unsafe {
            *out_sa_start = m.sa_start;
            *out_occ = m.occ;
        }
    }
    0
}

/// Cap-bounded one-shot maximal forward match — BWA-MEME's `min_intv`-bounded
/// SMEM interval counting (gap A). `*out_match_len`/`*out_sa_start`/`*out_occ`
/// are ALWAYS written. When the true `occ <= max_intv` the outputs are
/// byte-identical to `prmi_mem_search` (with `WANT_INTERVAL`); when the true
/// `occ > max_intv`, prmi stops the outward interval scan early and writes
/// `*out_occ == max_intv + 1` WITHOUT galloping to the exact wide interval (the
/// dominant cost on the repetitive tail), so `*out_sa_start` is then a partial
/// bound — the caller treats `occ > max_intv` as "too repetitive".
///
/// Returns 0 on success; `-1` null pointer; `-2` `query_len < 0` or
/// `pac_num_bases` too large for this platform; `-3` internal panic.
///
/// # Safety
/// `handle` valid; `query` valid for `query_len` bytes; `pac` valid for
/// `ceil(pac_num_bases/4)` bytes; `out_match_len`/`out_sa_start`/`out_occ`
/// writable.
#[allow(clippy::too_many_arguments)]
#[no_mangle]
pub unsafe extern "C" fn prmi_mem_search_capped(
    handle: *const prmi_index_t,
    query: *const u8,
    query_len: c_int,
    max_intv: u64,
    pac: *const u8,
    pac_num_bases: u64,
    out_match_len: *mut u32,
    out_sa_start: *mut u64,
    out_occ: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null()
        || query.is_null()
        || pac.is_null()
        || out_match_len.is_null()
        || out_sa_start.is_null()
        || out_occ.is_null()
    {
        set_last_error("prmi_mem_search_capped: null pointer");
        return -1;
    }
    if query_len < 0 {
        set_last_error("prmi_mem_search_capped: query_len < 0");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    let q = unsafe { std::slice::from_raw_parts(query, query_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_mem_search_capped: pac_num_bases too large for this platform");
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        h.idx.mem_search_capped(q, max_intv, pac_slice, enc)
    }));
    let m = match res {
        Ok(m) => m,
        Err(_) => {
            set_last_error("prmi_mem_search_capped: internal panic");
            return -3;
        }
    };
    unsafe {
        *out_match_len = m.match_len as u32;
        *out_sa_start = m.sa_start;
        *out_occ = m.occ;
    }
    0
}

/// `min_intv`-truncated backward reseed returning the full interval (the
/// consumer's `zz_left_span_reseed` seed emission). Finds the largest left span
/// `L` in `[anchor_len, span_max]` whose length-`L` window occurs `>= min_intv`
/// times (floored at `anchor_len`) and writes its exact forward interval:
/// `*out_span = L`, `*out_sa_start`/`*out_occ` = the interval. `(sa_start,
/// occ_count, anchor_len)` is the right anchor and its interval; same
/// `read`/`pivot` convention as `prmi_mem_search_backward`. `est_hint == 0` model-
/// launches the span search; `est_hint > 0` TRUSTS it as the inverse-SA index of
/// the anchor's locus (only changes probe count when valid — an invalid hint
/// yields incorrect output), same `no_search` contract as `prmi_mem_search_backward`.
///
/// Locates `L*` by the RC-downward walk
/// (`mem_search_backward_truncated_interval_rc`): the cold (`est_hint == 0`)
/// reseed nests the candidate intervals in RC-strand space and expands outward,
/// avoiding the per-candidate model launch the binary-search form pays.
/// Byte-identical output to the binary-search form.
///
/// Returns 0 on success; `-1` null pointer; `-2` invalid `read_len`/`pivot`,
/// `est_hint` out of range, or `pac_num_bases` too large for this platform;
/// `-3` internal panic.
///
/// # Safety
/// `handle` valid; `read` valid for `read_len` bytes; `pac` valid for
/// `ceil(pac_num_bases/4)` bytes; `out_span`/`out_sa_start`/`out_occ` writable.
#[allow(clippy::too_many_arguments)]
#[no_mangle]
pub unsafe extern "C" fn prmi_mem_search_backward_truncated_interval(
    handle: *const prmi_index_t,
    sa_start: u64,
    occ_count: u64,
    anchor_len: u64,
    read: *const u8,
    read_len: c_int,
    pivot: c_int,
    min_intv: u64,
    pac: *const u8,
    pac_num_bases: u64,
    est_hint: u64,
    out_span: *mut u64,
    out_sa_start: *mut u64,
    out_occ: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null()
        || read.is_null()
        || pac.is_null()
        || out_span.is_null()
        || out_sa_start.is_null()
        || out_occ.is_null()
    {
        set_last_error("prmi_mem_search_backward_truncated_interval: null pointer");
        return -1;
    }
    if read_len <= 0 || pivot < 0 {
        set_last_error("prmi_mem_search_backward_truncated_interval: invalid read_len or pivot");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    if est_hint != 0 && est_hint >= h.idx.sa_num() {
        set_last_error("prmi_mem_search_backward_truncated_interval: est_hint out of range");
        return -2;
    }
    let r = unsafe { std::slice::from_raw_parts(read, read_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error(
                "prmi_mem_search_backward_truncated_interval: pac_num_bases too large for this platform",
            );
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        h.idx.mem_search_backward_truncated_interval_rc(
            sa_start,
            occ_count,
            anchor_len,
            r,
            pivot as usize,
            min_intv,
            est_hint,
            pac_slice,
            enc,
        )
    }));
    match res {
        Ok(m) => {
            unsafe {
                *out_span = m.match_len;
                *out_sa_start = m.sa_start;
                *out_occ = m.occ;
            }
            0
        }
        Err(_) => {
            set_last_error("prmi_mem_search_backward_truncated_interval: internal panic");
            -3
        }
    }
}

/// One-shot maximal exact BACKWARD (leftward) match — the backward twin of
/// `prmi_mem_search`. From the right anchor `(sa_start, occ_count, anchor_len)`
/// matching `read[pivot..pivot+anchor_len)`, extend leftward and return the
/// deepest match in a single call. Same `read`/`pivot` convention as
/// `prmi_backward_spectrum` (full read, 2-bit 1 base/byte; extension goes to
/// `read[pivot-1]`, `read[pivot-2]`, …).
///
/// `*out_match_len` is ALWAYS written = the TOTAL matched span
/// (`anchor_len + left_ext`). With `flags & PRMI_MEM_WANT_INTERVAL`, also writes
/// `*out_sa_start`/`*out_occ` (the SA interval at the maximal match). When no
/// left extension is possible the anchor itself is returned (`match_len ==
/// anchor_len`); when `occ_count == 0`, all-zero.
///
/// `est_hint`: `0` → model-launch backward search (uses `sa_start`/`occ_count`).
/// `> 0` → an EXACT inverse-SA hint (`prmi_isa_at(refpos)` for the anchor's
/// reference position): prmi confirms the left extension directly against the
/// reference and skips the per-step model launch (BWA-MEME's `no_search` for the
/// left direction). The hint REPLACES the anchor interval, so `sa_start`/
/// `occ_count` are ignored. The result is byte-identical to `est_hint == 0`
/// whenever the hint is at a maximal-extension locus; a stale/diverged hint
/// yields a SHORTER `*out_match_len` (the caller's signal to fall back to
/// `est_hint == 0`). A hint `>= sa_num` returns `-2`.
///
/// Byte-identity: the returned `(sa_start, occ, match_len)` equals the maximal
/// step `prmi_backward_spectrum` produces for the same inputs.
///
/// Returns 0 on success; `-1` null handle/pointer, `-2` `read_len <= 0`,
/// `pivot < 0`, `pac_num_bases` too large for this platform, or `est_hint >= sa_num`;
/// `-3` internal panic.
///
/// # Safety
/// `handle` valid; `read` valid for `read_len` bytes; `pac` valid for
/// `ceil(pac_num_bases/4)` bytes; `out_match_len` writable; with the flag,
/// `out_sa_start`/`out_occ` writable.
#[allow(clippy::too_many_arguments)]
#[no_mangle]
pub unsafe extern "C" fn prmi_mem_search_backward(
    handle: *const prmi_index_t,
    sa_start: u64,
    occ_count: u64,
    anchor_len: u64,
    read: *const u8,
    read_len: c_int,
    pivot: c_int,
    pac: *const u8,
    pac_num_bases: u64,
    est_hint: u64,
    flags: u32,
    out_match_len: *mut u32,
    out_sa_start: *mut u64,
    out_occ: *mut u64,
) -> c_int {
    clear_last_error();
    if handle.is_null() || read.is_null() || pac.is_null() || out_match_len.is_null() {
        set_last_error("prmi_mem_search_backward: null pointer");
        return -1;
    }
    // Validate interval out-ptrs up front so an error return leaves outputs
    // untouched (see prmi_mem_search).
    if flags & PRMI_MEM_WANT_INTERVAL != 0 && (out_sa_start.is_null() || out_occ.is_null()) {
        set_last_error("prmi_mem_search_backward: WANT_INTERVAL set but out_sa_start/out_occ null");
        return -1;
    }
    if read_len <= 0 || pivot < 0 {
        set_last_error("prmi_mem_search_backward: invalid read_len or pivot");
        return -2;
    }
    let h = unsafe { Handle::as_ref(handle) };
    // est_hint == 0 → model-launch backward search (uses sa_start/occ_count);
    // > 0 → exact ISA launch (no_search): the hint replaces the anchor interval,
    // so sa_start/occ_count are ignored. Out-of-range hint is a caller error.
    if est_hint != 0 && est_hint >= h.idx.sa_num() {
        set_last_error("prmi_mem_search_backward: est_hint out of range");
        return -2;
    }
    let want_interval = flags & PRMI_MEM_WANT_INTERVAL != 0;
    let r = unsafe { std::slice::from_raw_parts(read, read_len as usize) };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_mem_search_backward: pac_num_bases too large for this platform");
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        if est_hint == 0 {
            h.idx.mem_search_backward(
                sa_start,
                occ_count,
                anchor_len,
                r,
                pivot as usize,
                pac_slice,
                enc,
            )
        } else {
            h.idx.mem_search_backward_from_hint(
                r,
                pivot as usize,
                anchor_len,
                est_hint,
                want_interval,
                pac_slice,
                enc,
            )
        }
    }));
    let m = match res {
        Ok(m) => m,
        Err(_) => {
            set_last_error("prmi_mem_search_backward: internal panic");
            return -3;
        }
    };
    unsafe { *out_match_len = m.match_len as u32 };
    if flags & PRMI_MEM_WANT_INTERVAL != 0 {
        unsafe {
            *out_sa_start = m.sa_start;
            *out_occ = m.occ;
        }
    }
    0
}

/// Reverse-complement a tokenized 32-mer key (2-bit packed, MSB-first).
/// `len` is the number of valid bases (1..=32; values outside that range
/// are clamped to 32). Writes the rev-comp key to *out_key.
///
/// Returns 0 on success; -1 if out_key is null.
///
/// # Safety
/// `out_key` must be a valid writable u64 location.
#[no_mangle]
pub unsafe extern "C" fn prmi_reverse_complement_key(
    key: u64,
    len: c_int,
    out_key: *mut u64,
) -> c_int {
    clear_last_error();
    if out_key.is_null() {
        set_last_error("prmi_reverse_complement_key: null out_key");
        return -1;
    }
    // Match main's FFI contract: a non-positive `len` (including 0) means "use
    // the full 32-mer", not "zero valid bases" — callers pass 0 to mean a full
    // key, never an empty one.
    let n = if len <= 0 { 32 } else { (len as usize).min(32) };
    let rc = prmi::encoding::reverse_complement_key(key, n);
    unsafe { *out_key = rc };
    0
}

/// Reverse-complement a 2-bit unpacked base array (1 base per byte,
/// values 0..=3; A=0, C=1, G=2, T=3). Writes `len` bytes to `out`.
///
/// `in_` and `out` may overlap arbitrarily. The common cases — `out == in_` (an
/// in-place transform) and fully disjoint buffers — take an allocation-free
/// two-ended walk, reading each pair before writing it so full alias is correct.
/// The rare PARTIAL-overlap case (the buffers share some but not all bytes, where
/// the two-ended walk would clobber not-yet-read input) falls back to a scratch
/// buffer, preserving the byte-identical result of the prior implementation.
///
/// Returns 0 on success; -1 if `in_` or `out` is null, or `len < 0`.
///
/// # Safety
/// `in_` must point to at least `len` valid bytes when `len > 0`.
/// `out` must point to at least `len` writable bytes when `len > 0`.
#[no_mangle]
pub unsafe extern "C" fn prmi_reverse_complement_2bit(
    in_: *const u8,
    len: c_int,
    out: *mut u8,
) -> c_int {
    clear_last_error();
    if in_.is_null() || out.is_null() || len < 0 {
        set_last_error("prmi_reverse_complement_2bit: null pointer or negative len");
        return -1;
    }
    let n = len as usize;
    if n == 0 {
        return 0;
    }
    // Partial overlap (buffers share some but not all bytes, and `out != in_`)
    // is the only case the in-place two-ended walk cannot handle: writing one end
    // would clobber input the opposite end has not read yet. Detect it by raw
    // pointer ranges and fall back to a scratch buffer, matching the prior
    // (always-allocating) implementation byte-for-byte. Full alias (`out == in_`)
    // and disjoint buffers take the allocation-free fast path below.
    let in_start = in_ as usize;
    let out_start = out as usize;
    let in_end = in_start.saturating_add(n);
    let out_end = out_start.saturating_add(n);
    let partial_overlap = in_start != out_start && in_start < out_end && out_start < in_end;
    if partial_overlap {
        let mut tmp = Vec::with_capacity(n);
        unsafe {
            for i in 0..n {
                tmp.push((*in_.add(n - 1 - i) & 0x3) ^ 0x3);
            }
            std::ptr::copy_nonoverlapping(tmp.as_ptr(), out, n);
        }
        return 0;
    }
    // Two-ended complement-and-reverse directly into `out`, no allocation. Each
    // pair is read into locals before either end is written, so this is correct
    // even when `out` and `in_` fully overlap (alias the same buffer). Raw
    // pointer reads/writes (not slices) avoid forming aliasing &/&mut.
    unsafe {
        let mut lo = 0usize;
        let mut hi = n - 1;
        while lo < hi {
            let a = *in_.add(lo);
            let b = *in_.add(hi);
            *out.add(lo) = (b & 0x3) ^ 0x3;
            *out.add(hi) = (a & 0x3) ^ 0x3;
            lo += 1;
            hi -= 1;
        }
        if lo == hi {
            // Odd length: complement the middle base in place.
            let m = *in_.add(lo);
            *out.add(lo) = (m & 0x3) ^ 0x3;
        }
    }
    0
}

/// One SMEM in the C ABI — the layout the consumer `memcpy`s into its `SMEM[]`.
/// `#[repr(C)]`, field-for-field identical to `prmi::index::collect::Smem`
/// (a const layout assertion below pins size + alignment).
#[repr(C)]
pub struct prmi_smem_t {
    /// Read index (stamped into every emitted SMEM; the consumer groups by it).
    pub rid: u32,
    /// Match start in the read (inclusive).
    pub m: u32,
    /// Match end in the read (inclusive).
    pub n: u32,
    /// SA-interval start index (raw 2× SA).
    pub k: i64,
    /// Reverse-complement bi-interval start; always 0 on the learned path.
    pub l: i64,
    /// Occurrence count = SA-interval size.
    pub s: i64,
}

/// SMEM-collection parameters, mirroring the bwa-mem3 `mem_opt_t` fields the
/// seeding walk reads. `split_len` is the caller-precomputed
/// `round(min_seed_len * split_factor)`. `max_mem_intv == 0` skips pass 3.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct prmi_collect_opts_t {
    /// Minimum seed length; emitted SMEMs span `>= min_seed_len`.
    pub min_seed_len: u32,
    /// Reseed length threshold: pass-1 SMEMs with span `>= split_len` are reseeded.
    pub split_len: u32,
    /// Reseed occurrence threshold: only pass-1 SMEMs with `s <= split_width`.
    pub split_width: i64,
    /// Pass-3 `max_mem_intv` strategy (the FMI long-MEM reseed round); `0` disables
    /// pass 3.
    pub max_mem_intv: i64,
}

/// `prmi_smem_t` and `prmi::index::collect::Smem` are both `#[repr(C)]` with the
/// same fields in the same order, so an output buffer of one can be filled in
/// place as a slice of the other. This guards size/alignment (and, given identical
/// `#[repr(C)]` field types/order, therefore the field offsets too).
const _: () = {
    assert!(
        core::mem::size_of::<prmi_smem_t>() == core::mem::size_of::<prmi::index::collect::Smem>()
    );
    assert!(
        core::mem::align_of::<prmi_smem_t>() == core::mem::align_of::<prmi::index::collect::Smem>()
    );
};

/// Collect ALL SMEMs for ONE read (passes 1+2[+3], sorted within-read)
/// byte-identically to bwa-mem3 FMI seeding — the fused entrypoint that runs the
/// whole zigzag walk in one call instead of the consumer's 91–155 per-read
/// `prmi_mem_search*` crossings. Pass 3 (the FMI long-MEM reseed round) is enabled
/// when `opts.max_mem_intv > 0` and disabled when `opts.max_mem_intv == 0`.
///
/// `read` is 2-bit encoded (`0..=3`, `4` = N), `read_len` bytes. `rid` is stamped
/// into every emitted `prmi_smem_t::rid`. `pac` is the FORWARD pac (bntpac packed,
/// `ceil(pac_num_bases/4)` bytes). The SMEMs are written to `out[..*out_n]`;
/// `out_cap` is the slot capacity.
///
/// An EMPTY read (`read_len == 0`) is valid — it yields 0 SMEMs (unlike the
/// per-query `prmi_mem_search*` entrypoints, which reject `read_len <= 0`); `read`
/// may be NULL in that case (the canonical C empty-slice representation).
///
/// Returns 0 on success (`*out_n` = SMEM count); `-1` null pointer (null `handle`/
/// `opts`/`pac`/`out_n`, null `read` with nonzero `read_len`, or null `out` with
/// nonzero `out_cap`); `-2` invalid `read_len`/`out_cap` or `pac_num_bases` too
/// large for this platform; `-3` internal panic; `-4` `out` too small (`*out_n` is
/// set to the required count — grow and retry).
///
/// # Safety
/// `handle` valid; `read` valid for `read_len` bytes; `opts` valid; `pac` valid for
/// `ceil(pac_num_bases/4)` bytes; `out` valid for `out_cap` `prmi_smem_t` slots (may
/// be null iff `out_cap == 0`); `out_n` writable.
#[allow(clippy::too_many_arguments)]
#[no_mangle]
pub unsafe extern "C" fn prmi_collect_smems(
    handle: *const prmi_index_t,
    read: *const u8,
    read_len: c_int,
    rid: u32,
    opts: *const prmi_collect_opts_t,
    pac: *const u8,
    pac_num_bases: u64,
    out: *mut prmi_smem_t,
    out_cap: c_int,
    out_n: *mut c_int,
) -> c_int {
    clear_last_error();
    if handle.is_null() || opts.is_null() || pac.is_null() || out_n.is_null() {
        set_last_error("prmi_collect_smems: null pointer");
        return -1;
    }
    // Unlike the per-query `prmi_mem_search*` entrypoints (which reject
    // `read_len <= 0`), an empty read is VALID here: a whole-read collector over an
    // empty read yields 0 SMEMs (`Ok(0)`). Only a negative length is an error.
    if read_len < 0 || out_cap < 0 {
        set_last_error("prmi_collect_smems: invalid read_len or out_cap");
        return -2;
    }
    // `read`/`out` may be NULL only for the empty case (the canonical C empty-slice
    // representation, `NULL + 0`); a NULL pointer with a nonzero length is an error.
    if read.is_null() && read_len != 0 {
        set_last_error("prmi_collect_smems: null read with nonzero read_len");
        return -1;
    }
    if out.is_null() && out_cap != 0 {
        set_last_error("prmi_collect_smems: null out with nonzero out_cap");
        return -1;
    }
    let o = unsafe { &*opts };
    let h = unsafe { Handle::as_ref(handle) };
    // `from_raw_parts` requires a non-null pointer even for length 0, so build an
    // empty slice directly for the empty case (mirrors `out_slice` below); `read`
    // is guaranteed non-null when `read_len > 0` by the check above.
    let r: &[u8] = if read_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(read, read_len as usize) }
    };
    let copts = prmi::index::collect::CollectOpts {
        min_seed_len: o.min_seed_len,
        split_len: o.split_len,
        split_width: o.split_width,
        max_mem_intv: o.max_mem_intv,
    };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_collect_smems: pac_num_bases too large for this platform");
            return -2;
        }
    };
    let pac_slice = unsafe { std::slice::from_raw_parts(pac, pac_bytes) };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    // Reinterpret the prmi_smem_t output buffer as a Smem slice (layout-asserted).
    let out_slice: &mut [prmi::index::collect::Smem] = if out_cap == 0 {
        &mut []
    } else {
        unsafe {
            std::slice::from_raw_parts_mut(out as *mut prmi::index::collect::Smem, out_cap as usize)
        }
    };
    // Reuse a per-thread scratch across calls so the per-read SMEM/reseed buffers are
    // allocated once per worker thread, not once per read. `collect_smems_into` clears
    // the scratch on entry, so this is byte-identical to `collect_smems`; it only
    // amortizes the two allocations over the millions of per-read calls the consumer
    // makes. Each C worker thread that calls `prmi_collect_smems` gets its own scratch
    // (thread-local), preserving the entrypoint's thread-safety.
    thread_local! {
        static SCRATCH: std::cell::RefCell<prmi::index::collect::CollectScratch> =
            std::cell::RefCell::new(prmi::index::collect::CollectScratch::new());
    }
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        SCRATCH.with(|cell| {
            let mut scratch = cell.borrow_mut();
            h.idx
                .collect_smems_into(r, rid, &copts, pac_slice, enc, out_slice, &mut scratch)
        })
    }));
    match res {
        Ok(Ok(n)) => {
            unsafe {
                *out_n = n as c_int;
            }
            0
        }
        Ok(Err(needed)) => {
            unsafe {
                *out_n = needed as c_int;
            }
            -4
        }
        Err(_) => {
            set_last_error("prmi_collect_smems: internal panic");
            -3
        }
    }
}

/// Tiered-dispatch presence pre-reject: does the read's first full 32-mer window
/// occur in this index? Wraps [`prmi::index::collect::LearnedIndex::present_anchor`]
/// — one cheap `mem_search` locate, far cheaper than a full `prmi_collect_smems`
/// whose failed reseeds on an absent read cost hundreds of probes. A Design-Z
/// (tiered) consumer calls this on a small fast-path index to route off-target
/// reads to the whole-genome fallback before paying the full fast-path search.
///
/// `read` is 2-bit-decoded query bases (`0..=3`, `4` = N; N-containing windows are
/// skipped). `pac` is the reference in BWA-MEME `bntpac` packing (2 bits/base,
/// MSB-first) with `pac_num_bases` bases — the same `(pac, pac_num_bases)` passed
/// to [`prmi_collect_smems`].
///
/// Returns `1` if present, `0` if absent, and a negative code on error
/// (`-1` null pointer, `-2` invalid `read_len`/`pac_num_bases`, `-3` internal panic).
///
/// # Safety
/// `handle` must come from [`prmi_open`]/[`prmi_open_shm`]. `read` must be valid for
/// `read_len` bytes (or NULL iff `read_len == 0`); `pac` must be valid for
/// `ceil(pac_num_bases / 4)` bytes, or NULL iff `pac_num_bases == 0` (the
/// canonical empty PAC, which maps to an empty slice).
#[no_mangle]
pub unsafe extern "C" fn prmi_present(
    handle: *const prmi_index_t,
    read: *const u8,
    read_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
) -> c_int {
    clear_last_error();
    // `pac == NULL` is allowed ONLY for the canonical empty PAC (`pac_num_bases
    // == 0`), which maps to an empty slice below; a NULL with a nonzero length is
    // a contract violation.
    if handle.is_null() || (pac.is_null() && pac_num_bases != 0) {
        set_last_error("prmi_present: null pointer");
        return -1;
    }
    if read_len < 0 {
        set_last_error("prmi_present: invalid read_len");
        return -2;
    }
    if read.is_null() && read_len != 0 {
        set_last_error("prmi_present: null read with nonzero read_len");
        return -1;
    }
    let h = unsafe { Handle::as_ref(handle) };
    // `packed_pac_bytes` only guards against `pac_num_bases` narrowing/overflow on
    // this platform; it does not catch a `pac` buffer that is the wrong size for
    // the loaded reference. Reject any `pac_num_bases` that disagrees with the
    // index's own `l_pac` BEFORE building the slice, so `from_raw_parts` can never
    // over-read a too-short caller buffer (UB). In correct usage the consumer
    // passes the reference's true `(pac, l_pac)` — the same pair given to
    // `prmi_collect_smems` — so this only rejects misuse. `l_pac()` is an infallible
    // metadata read, but fence it anyway so a panic here returns the documented `-3`
    // instead of crossing the C ABI (this runs before the `present_anchor` fence).
    let l_pac = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| h.idx.l_pac())) {
        Ok(v) => v,
        Err(_) => {
            set_last_error("prmi_present: internal panic");
            return -3;
        }
    };
    if pac_num_bases != l_pac {
        set_last_error("prmi_present: pac_num_bases does not match index l_pac");
        return -2;
    }
    let r: &[u8] = if read_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(read, read_len as usize) }
    };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_present: pac_num_bases too large for this platform");
            return -2;
        }
    };
    // `from_raw_parts` requires a non-null, aligned pointer even for len 0, so the
    // empty PAC (`pac_bytes == 0`, which `pac == NULL` is allowed for) maps to a
    // genuine empty slice rather than `from_raw_parts(NULL, 0)` (UB).
    let pac_slice: &[u8] = if pac_bytes == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(pac, pac_bytes) }
    };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        h.idx.present_anchor(r, pac_slice, enc)
    }));
    match res {
        Ok(true) => 1,
        Ok(false) => 0,
        Err(_) => {
            set_last_error("prmi_present: internal panic");
            -3
        }
    }
}

/// Bloom-accelerated ANY-window tiered-dispatch gate (Design-Z item-6 follow-up).
/// Wraps [`prmi::index::collect::LearnedIndex::present_anchor_bloom`].
///
/// When the sidecar carries a `.blm` (built via `prmi build --with-bloom`), this
/// tests EVERY N-free 32-mer window against the bloom and confirms each hit with
/// one `mem_search`, so it routes exactly the reads the exact any-window gate
/// would — recovering the ~46–48% of *servable* reads the first-window
/// [`prmi_present`] mis-routes to the fallback — without paying a locate on every
/// window of a truly-absent read. When no `.blm` is loaded it falls back to the
/// cheap first-window gate (identical to [`prmi_present`]), so it is a safe
/// drop-in replacement.
///
/// Arguments and safety requirements are identical to [`prmi_present`]. Returns
/// `1` present, `0` absent, or a negative error code: `-1` null/invalid pointer,
/// `-2` invalid `read_len`/`pac_num_bases` or PAC metadata mismatch (length, or
/// `pac_num_bases != l_pac`), `-3` internal panic.
///
/// # Safety
/// `handle` must come from [`prmi_open`]/[`prmi_open_shm`]. `read` must be valid
/// for `read_len` bytes (or NULL iff `read_len == 0`); `pac` must be valid for
/// `ceil(pac_num_bases / 4)` bytes, or NULL iff `pac_num_bases == 0` (the
/// canonical empty PAC, which maps to an empty slice).
#[no_mangle]
pub unsafe extern "C" fn prmi_present_bloom(
    handle: *const prmi_index_t,
    read: *const u8,
    read_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
) -> c_int {
    clear_last_error();
    // `pac == NULL` is allowed only for the canonical empty PAC (`pac_num_bases
    // == 0`); a NULL with nonzero length is a contract violation.
    if handle.is_null() || (pac.is_null() && pac_num_bases != 0) {
        set_last_error("prmi_present_bloom: null pointer");
        return -1;
    }
    if read_len < 0 {
        set_last_error("prmi_present_bloom: invalid read_len");
        return -2;
    }
    if read.is_null() && read_len != 0 {
        set_last_error("prmi_present_bloom: null read with nonzero read_len");
        return -1;
    }
    let h = unsafe { Handle::as_ref(handle) };
    // Mirror `prmi_present`: reject a `pac_num_bases` that disagrees with the
    // index's `l_pac` BEFORE building the slice. `packed_pac_bytes` only guards
    // platform narrowing, not a too-short caller buffer, so without this an
    // oversized `pac_num_bases` makes `from_raw_parts` over-read (UB) before
    // `present_anchor_bloom`'s internal `validate_packed_pac` ever runs.
    let l_pac = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| h.idx.l_pac())) {
        Ok(v) => v,
        Err(_) => {
            set_last_error("prmi_present_bloom: internal panic");
            return -3;
        }
    };
    if pac_num_bases != l_pac {
        set_last_error("prmi_present_bloom: pac_num_bases does not match index l_pac");
        return -2;
    }
    let r: &[u8] = if read_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(read, read_len as usize) }
    };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error("prmi_present_bloom: pac_num_bases too large for this platform");
            return -2;
        }
    };
    // Empty PAC maps to a real empty slice, not `from_raw_parts(NULL, 0)` (UB).
    let pac_slice: &[u8] = if pac_bytes == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(pac, pac_bytes) }
    };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
        h.idx.present_anchor_bloom(r, pac_slice, enc)
    }));
    match res {
        Ok(true) => 1,
        Ok(false) => 0,
        Err(_) => {
            set_last_error("prmi_present_bloom: internal panic");
            -3
        }
    }
}

/// Shared body for the cheap first-window presence-gate FFI entrypoints (Lever 2:
/// [`prmi_present_bloom_first`], [`prmi_present_exact`]). Validates the pointers,
/// builds the `read`/`pac` slices, and runs `gate` under `catch_unwind`. `name` is
/// the entrypoint name used in error messages. Returns `1`/`0`/`<0` with exactly
/// the same codes and contract as [`prmi_present`].
///
/// # Safety
/// Same requirements as [`prmi_present`]: `handle` from [`prmi_open`]/[`prmi_open_shm`];
/// `read` valid for `read_len` bytes (or NULL iff `read_len == 0`); `pac` valid for
/// `ceil(pac_num_bases / 4)` bytes, or NULL iff `pac_num_bases == 0` (the
/// canonical empty PAC, which maps to an empty slice).
unsafe fn present_gate_first_window(
    name: &str,
    handle: *const prmi_index_t,
    read: *const u8,
    read_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
    gate: impl Fn(&LearnedIndex, &[u8], &[u8], prmi::index::smem::PacEncoding) -> bool,
) -> c_int {
    clear_last_error();
    // `pac == NULL` is allowed only for the canonical empty PAC (`pac_num_bases
    // == 0`); a NULL with nonzero length is a contract violation.
    if handle.is_null() || (pac.is_null() && pac_num_bases != 0) {
        set_last_error(&format!("{name}: null pointer"));
        return -1;
    }
    if read_len < 0 {
        set_last_error(&format!("{name}: invalid read_len"));
        return -2;
    }
    if read.is_null() && read_len != 0 {
        set_last_error(&format!("{name}: null read with nonzero read_len"));
        return -1;
    }
    let h = unsafe { Handle::as_ref(handle) };
    // Mirror `prmi_present`: reject a `pac_num_bases` that disagrees with the
    // index's `l_pac` BEFORE building the slice (covers both gate entrypoints that
    // route through this helper). `packed_pac_bytes` only guards platform
    // narrowing, not a too-short caller buffer, so an oversized `pac_num_bases`
    // would otherwise make `from_raw_parts` over-read (UB).
    let l_pac = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| h.idx.l_pac())) {
        Ok(v) => v,
        Err(_) => {
            set_last_error(&format!("{name}: internal panic"));
            return -3;
        }
    };
    if pac_num_bases != l_pac {
        set_last_error(&format!("{name}: pac_num_bases does not match index l_pac"));
        return -2;
    }
    let r: &[u8] = if read_len == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(read, read_len as usize) }
    };
    let pac_bytes = match packed_pac_bytes(pac_num_bases) {
        Some(b) => b,
        None => {
            set_last_error(&format!("{name}: pac_num_bases too large for this platform"));
            return -2;
        }
    };
    // Empty PAC maps to a real empty slice, not `from_raw_parts(NULL, 0)` (UB).
    let pac_slice: &[u8] = if pac_bytes == 0 {
        &[]
    } else {
        unsafe { std::slice::from_raw_parts(pac, pac_bytes) }
    };
    let enc = prmi::index::smem::PacEncoding::Packed {
        num_bases: pac_num_bases,
    };
    let res =
        std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| gate(&h.idx, r, pac_slice, enc)));
    match res {
        Ok(true) => 1,
        Ok(false) => 0,
        Err(_) => {
            set_last_error(&format!("{name}: internal panic"));
            -3
        }
    }
}

/// Cheap FIRST-WINDOW BLOOM dispatch gate (Design-Z Lever 2, A1). Wraps
/// [`prmi::index::collect::LearnedIndex::present_anchor_bloom_first`].
///
/// Makes the SAME routing decision as [`prmi_present`] (first N-free 32-mer window
/// only) but replaces that window's `mem_search` locate with a single in-memory
/// bloom probe — a few hash ops, no SA/pac access, index-size-independent. No false
/// negatives over the keep-set; ≈`fp_rate` false positives (built at 0.01), which
/// the Design-Z consumer's present-read fallback (`--prmi-present-fallback`) absorbs
/// harmlessly. When no `.blm` is loaded it falls back to the exact first-window
/// [`prmi_present`], so it is a safe drop-in.
///
/// Arguments and safety requirements are identical to [`prmi_present`]. Returns
/// `1` present, `0` absent, or a negative error code: `-1` null/invalid pointer,
/// `-2` invalid `read_len`/`pac_num_bases` or PAC metadata mismatch (length, or
/// `pac_num_bases != l_pac`), `-3` internal panic.
///
/// # Safety
/// See [`prmi_present`].
#[no_mangle]
pub unsafe extern "C" fn prmi_present_bloom_first(
    handle: *const prmi_index_t,
    read: *const u8,
    read_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
) -> c_int {
    unsafe {
        present_gate_first_window(
            "prmi_present_bloom_first",
            handle,
            read,
            read_len,
            pac,
            pac_num_bases,
            |idx, r, pac_slice, enc| idx.present_anchor_bloom_first(r, pac_slice, enc),
        )
    }
}

/// Cheap EXACT first-window dispatch gate (Design-Z Lever 2, A2). Wraps
/// [`prmi::index::collect::LearnedIndex::present_anchor_exact`].
///
/// Makes the SAME routing decision and produces the SAME verdict as [`prmi_present`]
/// (`mem_search(window).match_len >= 32` on the first N-free window) but via
/// `kmer_exists`, which skips `mem_search`'s two interval-recovery gallops the gate
/// never reads — exact (no false positives) and modestly cheaper than the
/// `mem_search` first-window gate. Use when the bloom A1 gate's false positives are
/// not acceptable and the per-read gate cost still matters.
///
/// Arguments and safety requirements are identical to [`prmi_present`]. Returns
/// `1` present, `0` absent, or a negative error code: `-1` null/invalid pointer,
/// `-2` invalid `read_len`/`pac_num_bases` or PAC metadata mismatch (length, or
/// `pac_num_bases != l_pac`), `-3` internal panic.
///
/// # Safety
/// See [`prmi_present`].
#[no_mangle]
pub unsafe extern "C" fn prmi_present_exact(
    handle: *const prmi_index_t,
    read: *const u8,
    read_len: c_int,
    pac: *const u8,
    pac_num_bases: u64,
) -> c_int {
    unsafe {
        present_gate_first_window(
            "prmi_present_exact",
            handle,
            read,
            read_len,
            pac,
            pac_num_bases,
            |idx, r, pac_slice, enc| idx.present_anchor_exact(r, pac_slice, enc),
        )
    }
}
